#include "agent/eval/types.hpp"

#include <set>

namespace agent_framework::eval {
namespace {using json=nlohmann::json;template<typename T,typename B>std::optional<T> decode_value(const json&v,const char*k,const std::set<std::string>&f,const contracts::ParseContext&c,std::vector<contracts::ContractIssue>*i,B b){auto d=contracts::parse_typed_contract(v,k,c,i);if(!d||!contracts::validate_object_fields(d->payload,f,f,contracts::UnknownFieldPolicy::Reject,nullptr,i,"/payload"))return std::nullopt;try{T r=b(d->payload);r.metadata=std::move(d->metadata);return r;}catch(const std::exception&e){contracts::append_issue(i,"payload_decode_failed","/payload",e.what());return std::nullopt;}}}
json encode(const DatasetCase&v){return contracts::make_typed_contract(v.metadata,"agent.eval_dataset_case/v1",{{"case_id",v.case_id},{"input",v.input},{"environment",v.environment},{"ground_truth",v.ground_truth},{"criterion_ids",v.criterion_ids},{"tags",v.tags},{"license",v.license},{"dataset_version",v.dataset_version}});}
json encode(const Trajectory&v){return contracts::make_typed_contract(v.metadata,"agent.eval_trajectory/v1",{{"case_id",v.case_id},{"component_version",v.component_version},{"environment_digest",v.environment_digest},{"event_digests",v.event_digests},{"acceptance_report_digest",v.acceptance_report_digest},{"started_at",v.started_at},{"finished_at",v.finished_at}});}
json encode(const ComparisonResult&v){return contracts::make_typed_contract(v.metadata,"agent.eval_comparison/v1",{{"baseline_version",v.baseline_version},{"candidate_version",v.candidate_version},{"metric_result_digests",v.metric_result_digests},{"decision",v.decision},{"regressions",v.regressions}});}
std::optional<DatasetCase> decode_dataset_case(const json&v,const contracts::ParseContext&c,std::vector<contracts::ContractIssue>*i){static const std::set<std::string>f={"case_id","input","environment","ground_truth","criterion_ids","tags","license","dataset_version"};return decode_value<DatasetCase>(v,"agent.eval_dataset_case/v1",f,c,i,[](const json&p){DatasetCase r;r.case_id=p.at("case_id").get<std::string>();r.input=p.at("input").get<std::string>();r.environment=p.at("environment");r.ground_truth=p.at("ground_truth");r.criterion_ids=p.at("criterion_ids").get<std::vector<std::string>>();r.tags=p.at("tags").get<std::vector<std::string>>();r.license=p.at("license").get<std::string>();r.dataset_version=p.at("dataset_version").get<std::string>();return r;});}
std::optional<Trajectory> decode_trajectory(const json&v,const contracts::ParseContext&c,std::vector<contracts::ContractIssue>*i){static const std::set<std::string>f={"case_id","component_version","environment_digest","event_digests","acceptance_report_digest","started_at","finished_at"};return decode_value<Trajectory>(v,"agent.eval_trajectory/v1",f,c,i,[](const json&p){Trajectory r;r.case_id=p.at("case_id").get<std::string>();r.component_version=p.at("component_version").get<std::string>();r.environment_digest=p.at("environment_digest").get<std::string>();r.event_digests=p.at("event_digests").get<std::vector<std::string>>();r.acceptance_report_digest=p.at("acceptance_report_digest").get<std::string>();r.started_at=p.at("started_at").get<std::string>();r.finished_at=p.at("finished_at").get<std::string>();return r;});}
std::optional<ComparisonResult> decode_comparison_result(const json&v,const contracts::ParseContext&c,std::vector<contracts::ContractIssue>*i){static const std::set<std::string>f={"baseline_version","candidate_version","metric_result_digests","decision","regressions"};return decode_value<ComparisonResult>(v,"agent.eval_comparison/v1",f,c,i,[](const json&p){ComparisonResult r;r.baseline_version=p.at("baseline_version").get<std::string>();r.candidate_version=p.at("candidate_version").get<std::string>();r.metric_result_digests=p.at("metric_result_digests").get<std::vector<std::string>>();r.decision=p.at("decision").get<std::string>();r.regressions=p.at("regressions").get<std::vector<std::string>>();return r;});}
}  // namespace agent_framework::eval
